import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Consider a finite simple graph G on {n_vertices} vertices. For any two non-adjacent vertices, they have exactly {mu} common neighbors. There exist adjacent vertices v_1 and v_2 with no common neighbors, and d(v_1) = {k1}. Define M = max(d(v_2) − d(v_1)) if such a graph G exists, and M = 0 otherwise. Let a be the smallest positive real root of the equation P(x) = M · Q(x), where P(x) = x^3 − {t}x^2 − {u} and Q(x) = 2x^3 − {q2}x^2 + {q1}x − {q0} − M. Compute the remainder of the closest integer to a^{[power_n]} when divided by {modulus}. After solving, output your final answer in the following format:\n### The final answer is: \\boxed{<answer>}'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# generate parameters ensuring the rounding argument and non-trivial recurrence
while True:
    n_vertices = rng.randint(50, 150)
    mu = rng.randint(2, 5)
    k1 = rng.randint(9, 20)
    t = rng.randint(7, 12)
    u = rng.randint(2, 4)
    power_n = rng.randint(40, 80)
    modulus = 1000
    # ensure root a lies in (t, t+1) by making P(t) < 0 and P(t+1) > 0
    if u >= (t + 1) ** 2:
        continue
    # bound on conjugate magnitudes: |b|=|c|=sqrt(u/a) <= sqrt(u/t)
    rho = (u / t) ** 0.5
    # enforce small tail so nearest integer to a^power_n equals s_{power_n}
    if 2 * (rho ** power_n) >= 0.49:
        continue
    # auxiliary coefficients for Q(x); irrelevant when M=0 but included for generality
    q2 = rng.randint(t - 3, t + 4)
    q1 = rng.randint(1, 9)
    q0 = rng.randint(10, 30)
    return {
        'n_vertices': n_vertices,
        'mu': mu,
        'k1': k1,
        't': t,
        'u': u,
        'q2': q2,
        'q1': q1,
        'q0': q0,
        'power_n': power_n,
        'modulus': modulus
    }

    def verifier(assign):
# Validate inputs and compute the required remainder deterministically
# If constraints fail, return (False, None)
required = ['n_vertices','mu','k1','t','u','q2','q1','q0','power_n','modulus']
for k in required:
    if k not in assign:
        # missing assignment
        return (False, None)
n_vertices = assign['n_vertices']
mu = assign['mu']
k1 = assign['k1']
t = assign['t']
u = assign['u']
q2 = assign['q2']
q1 = assign['q1']
q0 = assign['q0']
N = assign['power_n']
mod = assign['modulus']
# basic domain checks
if not (isinstance(n_vertices, int) and n_vertices >= 3):
    return (False, None)
if not (isinstance(mu, int) and mu >= 1):
    return (False, None)
if not (isinstance(k1, int) and k1 >= 1):
    return (False, None)
if not (isinstance(t, int) and t >= 2):
    return (False, None)
if not (isinstance(u, int) and u >= 1):
    return (False, None)
if not (isinstance(N, int) and N >= 1):
    return (False, None)
if not (isinstance(mod, int) and mod >= 2):
    return (False, None)
# enforce the bracket and rounding bound used by the solution strategy
if u >= (t + 1) ** 2:
    # fails guarantee that a in (t, t+1)
    return (False, None)
rho = (u / t) ** 0.5
if 2 * (rho ** N) >= 0.49:
    # fails guarantee that nearest integer to a^N equals s_N
    return (False, None)
# Graph part: given the property and existence of an adjacent pair with no common neighbors, M=0 by a bijection between neighbor sets.
M = 0
# Polynomial part: a is the smallest positive root of P(x) = M Q(x), here P(x) since M=0.
# Use Newton sums for the monic cubic x^3 - t x^2 - u = 0.
# For roots a, b, c: s_n = a^n + b^n + c^n satisfies s_n = t s_{n-1} + u s_{n-3}, with s_0=3, s_1=t, s_2=t^2.
s0 = 3 % mod
s1 = t % mod
s2 = (t * t) % mod
if N == 0:
    ans = s0
elif N == 1:
    ans = s1
elif N == 2:
    ans = s2
else:
    s_nm3 = s0
    s_nm2 = s1
    s_nm1 = s2
    for _ in range(3, N + 1):
        s_n = (t * s_nm1 + u * s_nm3) % mod
        s_nm3, s_nm2, s_nm1 = s_nm2, s_nm1, s_n
    ans = s_nm1
return (True, ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

